package cn.zhuatech.privacy.deep;import cn.zhuatech.privacy.model.AuditLog;import cn.zhuatech.privacy.repository.AuditLogRepository;import jakarta.persistence.*;import jakarta.validation.constraints.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;import java.time.*;import java.util.*;
@Service @Transactional(readOnly=true) public class DeepDomainService{private final EntityManager em;private final AuditLogRepository audits;public DeepDomainService(EntityManager em,AuditLogRepository audits){this.em=em;this.audits=audits;}
 public PrivacyDashboard dashboard(String org){List<ActivityView> activities=em.createQuery("select a from ProcessingActivity a where a.organizationCode=:o order by a.createdAt desc",ProcessingActivity.class).setParameter("o",org).getResultList().stream().map(this::view).toList();List<RequestView> requests=em.createQuery("select r from SubjectRequest r where r.organizationCode=:o order by r.receivedAt desc",SubjectRequest.class).setParameter("o",org).getResultList().stream().map(this::view).toList();long activeConsent=em.createQuery("select count(c) from ConsentRecord c where c.organizationCode=:o and c.status='GRANTED'",Long.class).setParameter("o",org).getSingleResult(),overdue=requests.stream().filter(r->!Set.of("FULFILLED","REJECTED").contains(r.status())&&r.dueAt().isBefore(LocalDateTime.now())).count();return new PrivacyDashboard(activities,requests,activeConsent,overdue);}
 @Transactional public ActivityView createActivity(ActivityRequest r){ProcessingActivity a=new ProcessingActivity(r.organizationCode(),r.activityNo(),r.name(),r.department(),r.owner(),r.lawfulBasis(),r.dataCategories(),r.purpose(),r.sensitiveData(),r.crossBorder(),r.retentionDays());em.persist(a);audit("ROPA","创建处理活动",r.activityNo(),r.name());return view(a);}
 @Transactional public AssessmentView assess(Long activityId,AssessmentRequest r){activity(activityId);ImpactAssessment current=assessment(activityId);if(current!=null)throw conflict("该处理活动已存在影响评估");ImpactAssessment a=new ImpactAssessment(activityId,r.riskDescription(),r.mitigations(),r.residualRisk(),r.reviewer());em.persist(a);audit("PIA","提交影响评估",String.valueOf(activityId),r.residualRisk());return view(a);}
 @Transactional public AssessmentView approveAssessment(Long id){ImpactAssessment a=em.find(ImpactAssessment.class,id);if(a==null)throw notFound("影响评估不存在");if(!"DRAFT".equals(a.status))throw conflict("影响评估不能重复批准");if("HIGH".equals(a.residualRisk))throw conflict("剩余风险为HIGH时不得批准");a.status="APPROVED";a.approvedAt=LocalDateTime.now();audit("PIA","批准影响评估",String.valueOf(a.activityId),a.residualRisk);return view(a);}
 @Transactional public ActivityView submit(Long id){ProcessingActivity a=activity(id);if(!"DRAFT".equals(a.status))throw conflict("只有草稿处理活动可以提交");if(a.lawfulBasis==null||a.lawfulBasis.isBlank())throw conflict("必须明确合法性基础");if(a.retentionDays<=0)throw conflict("必须配置有效保留期限");if(a.sensitiveData||a.crossBorder){ImpactAssessment pia=assessment(id);if(pia==null||!"APPROVED".equals(pia.status))throw conflict("敏感个人信息或跨境活动必须完成并批准影响评估");}a.status="IN_REVIEW";audit("ROPA","提交合规复核",a.activityNo,a.lawfulBasis);return view(a);}
 @Transactional public ActivityView approveActivity(Long id){ProcessingActivity a=activity(id);if(!"IN_REVIEW".equals(a.status))throw conflict("只有待复核活动可以批准");a.status="APPROVED";a.approvedAt=LocalDateTime.now();audit("ROPA","批准处理活动",a.activityNo,a.owner);return view(a);}
 @Transactional public ConsentView grantConsent(ConsentRequest r){ConsentRecord c=new ConsentRecord(r.organizationCode(),r.subjectRef(),r.purposeCode(),r.noticeVersion(),r.source(),r.proofReference());em.persist(c);audit("CONSENT","记录同意",r.subjectRef(),r.purposeCode());return view(c);}@Transactional public ConsentView revokeConsent(Long id){ConsentRecord c=em.find(ConsentRecord.class,id);if(c==null)throw notFound("同意记录不存在");if(!"GRANTED".equals(c.status))throw conflict("同意已经撤回");c.status="REVOKED";c.revokedAt=LocalDateTime.now();audit("CONSENT","撤回同意",c.subjectRef,c.purposeCode);return view(c);}
 @Transactional public RequestView createRequest(SubjectRequestInput r){SubjectRequest q=new SubjectRequest(r.organizationCode(),r.requestNo(),r.subjectRef(),r.requestType(),r.channel());em.persist(q);audit("DSR","受理主体请求",r.requestNo(),r.requestType());return view(q);}@Transactional public RequestView verify(Long id,VerifyRequest r){SubjectRequest q=request(id);if(!"RECEIVED".equals(q.status))throw conflict("只有已受理请求可以核验身份");q.status="VERIFIED";q.assignee=r.assignee();q.verifiedAt=LocalDateTime.now();audit("DSR","身份核验",q.requestNo,r.assignee());return view(q);}@Transactional public RequestView fulfill(Long id,FulfillRequest r){SubjectRequest q=request(id);if(!"VERIFIED".equals(q.status))throw conflict("主体身份核验后才能履行请求");if(r.responseEvidence().isBlank())throw bad("履行证据不能为空");q.responseEvidence=r.responseEvidence();q.status="FULFILLED";q.completedAt=LocalDateTime.now();if("DELETE".equals(q.requestType)){List<ProcessingActivity> acts=em.createQuery("select a from ProcessingActivity a where a.organizationCode=:o and a.status='APPROVED'",ProcessingActivity.class).setParameter("o",q.organizationCode).getResultList();acts.forEach(a->em.persist(new DeletionTask(a.id,q.subjectRef,"SUBJECT_REQUEST",LocalDate.now())));}audit("DSR","履行主体请求",q.requestNo,r.responseEvidence());return view(q);}
 @Transactional public RetentionResult runRetention(String org,LocalDate asOf){List<ProcessingActivity> acts=em.createQuery("select a from ProcessingActivity a where a.organizationCode=:o and a.status='APPROVED'",ProcessingActivity.class).setParameter("o",org).getResultList();int created=0;for(var a:acts){if(a.createdAt.toLocalDate().plusDays(a.retentionDays).isBefore(asOf)){em.persist(new DeletionTask(a.id,"BATCH","RETENTION_EXPIRED",asOf));created++;}}audit("RETENTION","执行保留扫描",org,"created="+created);return new RetentionResult(created,asOf);}
 private ProcessingActivity activity(Long id){ProcessingActivity a=em.find(ProcessingActivity.class,id);if(a==null)throw notFound("处理活动不存在");return a;}private SubjectRequest request(Long id){SubjectRequest q=em.find(SubjectRequest.class,id);if(q==null)throw notFound("主体请求不存在");return q;}private ImpactAssessment assessment(Long activityId){return em.createQuery("select a from ImpactAssessment a where a.activityId=:id",ImpactAssessment.class).setParameter("id",activityId).getResultStream().findFirst().orElse(null);}private ActivityView view(ProcessingActivity a){return new ActivityView(a.id,a.organizationCode,a.activityNo,a.name,a.department,a.owner,a.lawfulBasis,a.sensitiveData,a.crossBorder,a.retentionDays,a.status,a.version);}private AssessmentView view(ImpactAssessment a){return new AssessmentView(a.id,a.activityId,a.riskDescription,a.mitigations,a.residualRisk,a.status,a.reviewer);}private ConsentView view(ConsentRecord c){return new ConsentView(c.id,c.subjectRef,c.purposeCode,c.noticeVersion,c.source,c.status,c.proofReference,c.grantedAt,c.revokedAt);}private RequestView view(SubjectRequest r){return new RequestView(r.id,r.requestNo,r.subjectRef,r.requestType,r.channel,r.status,r.assignee,r.receivedAt,r.dueAt,r.completedAt,r.version);}private void audit(String m,String a,String n,String d){audits.save(new AuditLog(m,a,n,"domain-service",d));}private ResponseStatusException bad(String m){return new ResponseStatusException(HttpStatus.BAD_REQUEST,m);}private ResponseStatusException conflict(String m){return new ResponseStatusException(HttpStatus.CONFLICT,m);}private ResponseStatusException notFound(String m){return new ResponseStatusException(HttpStatus.NOT_FOUND,m);}
 public record ActivityRequest(@NotBlank String organizationCode,@NotBlank String activityNo,@NotBlank String name,@NotBlank String department,@NotBlank String owner,String lawfulBasis,@NotBlank String dataCategories,@NotBlank String purpose,boolean sensitiveData,boolean crossBorder,@Positive int retentionDays){}public record AssessmentRequest(@NotBlank String riskDescription,@NotBlank String mitigations,@Pattern(regexp="LOW|MEDIUM|HIGH")String residualRisk,@NotBlank String reviewer){}public record ConsentRequest(@NotBlank String organizationCode,@NotBlank String subjectRef,@NotBlank String purposeCode,@NotBlank String noticeVersion,@NotBlank String source,@NotBlank String proofReference){}public record SubjectRequestInput(@NotBlank String organizationCode,@NotBlank String requestNo,@NotBlank String subjectRef,@Pattern(regexp="ACCESS|CORRECT|DELETE|WITHDRAW")String requestType,@NotBlank String channel){}public record VerifyRequest(@NotBlank String assignee){}public record FulfillRequest(@NotBlank String responseEvidence){}
 public record ActivityView(Long id,String organizationCode,String activityNo,String name,String department,String owner,String lawfulBasis,boolean sensitiveData,boolean crossBorder,int retentionDays,String status,long version){}public record AssessmentView(Long id,Long activityId,String riskDescription,String mitigations,String residualRisk,String status,String reviewer){}public record ConsentView(Long id,String subjectRef,String purposeCode,String noticeVersion,String source,String status,String proofReference,LocalDateTime grantedAt,LocalDateTime revokedAt){}public record RequestView(Long id,String requestNo,String subjectRef,String requestType,String channel,String status,String assignee,LocalDateTime receivedAt,LocalDateTime dueAt,LocalDateTime completedAt,long version){}public record RetentionResult(int deletionTasksCreated,LocalDate asOf){}public record PrivacyDashboard(List<ActivityView> activities,List<RequestView> requests,long activeConsents,long overdueRequests){}
}
